-- SQLite schema generated from the implemented JPA model. No data included.
PRAGMA foreign_keys=ON;

CREATE TABLE app_user_profile (enabled_in_business_system boolean not null, is_deleted boolean, locked_in_business_system boolean not null, created_at timestamp, deleted_at timestamp, general_directorate_id bigint, id integer, tax_affairs_office_id bigint, tax_unit_id bigint, updated_at timestamp, business_role varchar(255) check (business_role in ('GENERAL_OFFICE_HEAD','TAX_OFFICE_HEAD','TAX_UNIT_HEAD','TAX_EXPERT','ADMIN')), created_by varchar(255), deleted_by varchar(255), email varchar(255), first_name varchar(255), keycloak_user_id varchar(255) not null, last_name varchar(255), phone_number varchar(255), updated_by varchar(255), username varchar(255) not null, primary key (id), foreign key (general_directorate_id) references general_directorate_of_tax_affairs (id), foreign key (tax_affairs_office_id) references tax_affairs_office (id), foreign key (tax_unit_id) references tax_unit (id));

CREATE TABLE audit_log (created_at timestamp not null, id integer, new_value varchar(2000), old_value varchar(2000), action varchar(255) not null, actor_keycloak_user_id varchar(255), actor_username varchar(255), target_id varchar(255), target_type varchar(255) not null, primary key (id));

CREATE TABLE contact_info (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, legal_person_id bigint, natural_person_id bigint, updated_at timestamp, version bigint, created_by varchar(255), deleted_by varchar(255), email varchar(255), fax_no varchar(255), legal_address varchar(255), mobile_no varchar(255), phone_no varchar(255), postal_code varchar(255), updated_by varchar(255), website varchar(255), primary key (id), foreign key (legal_person_id) references legal_person (id), foreign key (natural_person_id) references natural_person (id));

CREATE TABLE contact_info_history (is_deleted boolean, contact_info_id bigint not null, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), legal_address varchar(255), phone_no varchar(255), postal_code varchar(255), updated_by varchar(255), primary key (id), foreign key (contact_info_id) references contact_info (id));

CREATE TABLE debt_detection_document (is_deleted boolean, created_at timestamp, deleted_at timestamp, execution_paper_id bigint, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), updated_by varchar(255), primary key (id), foreign key (execution_paper_id) references execution_paper (id));

CREATE TABLE debt_information (is_deleted boolean, created_at timestamp, current_amounts_as_of timestamp, deleted_at timestamp, execution_paper_id bigint unique, finalized_debt_paper_id bigint, id integer, last_debt_inquiry_at timestamp, updated_at timestamp, version bigint, aggregate_outstanding_debt_amount TEXT, aggregate_total_credit_amount TEXT, aggregate_total_duty_amount TEXT, aggregate_total_paid_amount TEXT, aggregate_total_penalty_amount TEXT, aggregate_total_remission_amount TEXT, aggregate_total_tax_amount TEXT, created_by varchar(255), deleted_by varchar(255), outstanding_debt_details TEXT, tax_credit_details TEXT, tax_liability_details TEXT, total_payments_details TEXT, total_penalties_details TEXT, total_remissions_details TEXT, updated_by varchar(255), primary key (id), foreign key (execution_paper_id) references execution_paper (id), foreign key (finalized_debt_paper_id) references finalized_debt_paper (id));

CREATE TABLE debt_information_history (archived_at timestamp, debt_information_id bigint not null, effective_at timestamp, id integer, aggregate_outstanding_debt_amount TEXT, aggregate_total_credit_amount TEXT, aggregate_total_duty_amount TEXT, aggregate_total_paid_amount TEXT, aggregate_total_penalty_amount TEXT, aggregate_total_remission_amount TEXT, aggregate_total_tax_amount TEXT, inquiry_request_id varchar(255), outstanding_debt_details TEXT, tax_credit_details TEXT, tax_liability_details TEXT, total_payments_details TEXT, total_penalties_details TEXT, total_remissions_details TEXT, primary key (id), foreign key (debt_information_id) references debt_information (id));

CREATE TABLE debt_inquiry_result (is_deleted boolean, created_at timestamp, deleted_at timestamp, effective_at timestamp, execution_paper_id bigint not null, id integer, received_at timestamp not null, updated_at timestamp, aggregate_outstanding_debt_amount TEXT, aggregate_total_credit_amount TEXT, aggregate_total_duty_amount TEXT, aggregate_total_paid_amount TEXT, aggregate_total_penalty_amount TEXT, aggregate_total_remission_amount TEXT, aggregate_total_tax_amount TEXT, created_by varchar(255), deleted_by varchar(255), hash varchar(255) not null, mapping_version varchar(255), request_id varchar(255) not null unique, response_json TEXT not null, updated_by varchar(255), primary key (id), foreign key (execution_paper_id) references execution_paper (id));

CREATE TABLE debt_paper_push_record (is_deleted boolean, source_period integer not null, source_year integer not null, created_at timestamp, deleted_at timestamp, execution_paper_id bigint, id integer, issuance_request_id bigint, received_at timestamp not null, source_document_id bigint, source_produce_date timestamp not null, updated_at timestamp, announcement_type varchar(255), created_by varchar(255), deleted_by varchar(255), failure_reason TEXT, follow_code varchar(255), mapping_version varchar(255), national_id varchar(255) not null, processing_status varchar(255) not null check (processing_status in ('RECEIVED','WAITING_IDENTITY','REJECTED_IDENTITY','NEEDS_REVIEW','WAITING_ORGANIZATION','PAPER_CREATED','SUCCESS','WORKFLOW_START_FAILED')), reference_id varchar(255) not null unique, second_parameter varchar(255), source_hash varchar(255), source_tax_office_code TEXT, tax_amount varchar(255), tax_source varchar(255) not null, trace_id varchar(255) not null, updated_by varchar(255), xml_payload TEXT not null, primary key (id), foreign key (execution_paper_id) references execution_paper (id), foreign key (source_document_id) references finalized_debt_paper (id));

CREATE TABLE execution_number_sequence (last_number integer not null, year integer not null, primary key (year));

CREATE TABLE execution_paper (is_deleted boolean, created_at timestamp, deleted_at timestamp, finalized_debt_paper_id bigint, id integer, issuance_date timestamp, sending_unit_id bigint, tax_unit_id bigint, taxpayer_id bigint, updated_at timestamp, created_by varchar(255), current_state varchar(255), deleted_by varchar(255), execution_paper_unique_code varchar(255) unique, issuance_finalization_reason varchar(255), tax_source varchar(255), updated_by varchar(255), primary key (id), foreign key (finalized_debt_paper_id) references finalized_debt_paper (id), foreign key (sending_unit_id) references tax_unit (id), foreign key (tax_unit_id) references tax_unit (id), foreign key (taxpayer_id) references taxpayer (id));

