CREATE TABLE execution_paper_rejection_rule (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), description TEXT, document_no varchar(255), end_date varchar(255), file_path varchar(255), rule_json TEXT, start_date varchar(255), updated_by varchar(255), primary key (id));

CREATE TABLE execution_paper_state_history (is_deleted boolean, created_at timestamp, deleted_at timestamp, execution_paper_id bigint, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), state varchar(255), state_date varchar(255), updated_by varchar(255), primary key (id), foreign key (execution_paper_id) references execution_paper (id));

