CREATE TABLE fake_sanim_debt_inquiry_request (is_deleted boolean, created_at timestamp, deleted_at timestamp, execution_paper_id bigint not null, id integer, responded_at timestamp, sent_at timestamp not null, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), error_message TEXT, request_id varchar(255) not null unique, response_payload TEXT, status varchar(255) not null, taxpayer_identifier varchar(255) not null, taxpayer_type varchar(255) not null check (taxpayer_type in ('NATURAL','LEGAL')), updated_by varchar(255), primary key (id));

CREATE TABLE fake_sanim_inform_request (is_deleted boolean, created_at timestamp, deleted_at timestamp, execution_paper_id bigint, id integer, updated_at timestamp, confirmed_at varchar(255), created_by varchar(255), debt_paper_id varchar(255), deleted_by varchar(255), error_message TEXT, inform_date varchar(255), message_type varchar(255), payload TEXT, rejection_reason_code varchar(255), rejection_reason_description TEXT, restriction_removal_date varchar(255), sent_at varchar(255), status varchar(255), updated_by varchar(255), primary key (id), foreign key (execution_paper_id) references execution_paper (id));

