CREATE TABLE general_directorate_of_tax_affairs (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, address varchar(255), created_by varchar(255), deleted_by varchar(255), general_directorate_name varchar(255), phone varchar(255), postal_code varchar(255), updated_by varchar(255), primary key (id));

