CREATE TABLE legal_person (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), national_id varchar(255) not null unique, updated_by varchar(255), primary key (id));

