CREATE TABLE legal_person_extra_info_history (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, legal_person_id bigint not null, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), name varchar(255), registration_date varchar(255), registration_number varchar(255), updated_by varchar(255), primary key (id), foreign key (legal_person_id) references legal_person (id));

CREATE TABLE natural_person (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), fida varchar(255) unique, national_code varchar(255) unique, updated_by varchar(255), primary key (id), check ((national_code IS NOT NULL AND fida IS NULL) OR (national_code IS NULL AND fida IS NOT NULL)));

CREATE TABLE natural_person_extra_info (arrest_status integer, capital_status integer, certificate_of_no_criminal_record integer, is_deleted boolean, is_foreign integer, management_declaration integer, created_at timestamp, deleted_at timestamp, id integer, natural_person_id bigint not null unique, updated_at timestamp, version bigint, birth_date varchar(255), created_by varchar(255), deleted_by varchar(255), father_name varchar(255), first_name varchar(255), first_name_en varchar(255), last_name varchar(255), last_name_en varchar(255), passport_expiry_date varchar(255), updated_by varchar(255), primary key (id), foreign key (natural_person_id) references natural_person (id));

