CREATE TABLE permission (enabled boolean not null, is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, code varchar(255) not null, created_by varchar(255), deleted_by varchar(255), description varchar(255), updated_by varchar(255), primary key (id));

CREATE TABLE related_person_post (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, code varchar(255) not null unique check (code in ('CEO','BOARD_CHAIR','BOARD_VICE_CHAIR','BOARD_MEMBER','ALTERNATE_BOARD_MEMBER','MANAGING_PARTNER','PARTNER','SHAREHOLDER','LEGAL_REPRESENTATIVE','LEGAL_ENTITY_REPRESENTATIVE','LIQUIDATOR','PRIMARY_INSPECTOR','ALTERNATE_INSPECTOR','PARENT_COMPANY','SUBSIDIARY','AFFILIATE')), created_by varchar(255), deleted_by varchar(255), updated_by varchar(255), primary key (id));

CREATE TABLE related_persons (has_signatory_authority integer, is_deleted boolean, is_non_board_member integer, is_non_partner integer, management_declaration integer, created_at timestamp, deleted_at timestamp, id integer, legal_person_id bigint, legal_representative_natural_person_id bigint, natural_person_id bigint, owner_legal_person_id bigint, post_id bigint, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), end_date varchar(255), last_synced_at varchar(255), position_expiry_date varchar(255), source_record_id varchar(255), source_system varchar(255), start_date varchar(255), updated_by varchar(255), primary key (id), foreign key (legal_person_id) references legal_person (id), foreign key (legal_representative_natural_person_id) references natural_person (id), foreign key (natural_person_id) references natural_person (id), foreign key (owner_legal_person_id) references legal_person (id), foreign key (post_id) references related_person_post (id));

CREATE TABLE restriction_request (is_deleted boolean, result integer, created_at timestamp, deleted_at timestamp, id integer, legal_person_id bigint, natural_person_id bigint, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), finalized_debt_paper_notification_id varchar(255), updated_by varchar(255), primary key (id), foreign key (legal_person_id) references legal_person (id), foreign key (natural_person_id) references natural_person (id));

CREATE TABLE sanim_audit_entry (is_deleted boolean, amount_rials bigint not null, created_at timestamp, deleted_at timestamp, id integer, occurred_at timestamp not null, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), description varchar(255), entry_type varchar(255) not null check (entry_type in ('DEBT','PAYMENT','PENALTY','CREDIT')), reference_no varchar(255), taxpayer_display_name varchar(255) not null, taxpayer_identifier varchar(255) not null, taxpayer_type varchar(255) not null check (taxpayer_type in ('NATURAL','LEGAL')), updated_by varchar(255), primary key (id));

CREATE TABLE tax_affairs_office (is_deleted boolean, office_type integer, created_at timestamp, deleted_at timestamp, general_directorate_of_tax_affairs_id bigint, id integer, updated_at timestamp, address varchar(255), created_by varchar(255), deleted_by varchar(255), office_code varchar(255) unique, office_name varchar(255), phone varchar(255), postal_code varchar(255), updated_by varchar(255), primary key (id), foreign key (general_directorate_of_tax_affairs_id) references general_directorate_of_tax_affairs (id));

CREATE TABLE tax_unit (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, tax_affairs_office_id bigint, updated_at timestamp, address varchar(255), created_by varchar(255), deleted_by varchar(255), phone varchar(255), postal_code varchar(255), tax_unit_name varchar(255), updated_by varchar(255), primary key (id), foreign key (tax_affairs_office_id) references tax_affairs_office (id));

CREATE TABLE taxpayer (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, legal_person_id bigint unique, natural_person_id bigint, updated_at timestamp, created_by varchar(255), deleted_by varchar(255), registration_trace_code varchar(255) not null unique, tin varchar(255) not null unique, updated_by varchar(255), primary key (id), check ((natural_person_id IS NOT NULL AND legal_person_id IS NULL) OR (natural_person_id IS NULL AND legal_person_id IS NOT NULL)), foreign key (legal_person_id) references legal_person (id), foreign key (natural_person_id) references natural_person (id));

CREATE TABLE taxpayer_activity_type (is_deleted boolean, created_at timestamp, deleted_at timestamp, id integer, taxpayer_id bigint not null unique, updated_at timestamp, version bigint, activity_type_code varchar(255), activity_type_title varchar(255), created_by varchar(255), deleted_by varchar(255), updated_by varchar(255), primary key (id), foreign key (taxpayer_id) references taxpayer (id));

CREATE TABLE taxpayer_activity_type_history (is_deleted boolean, activity_id bigint not null, created_at timestamp, deleted_at timestamp, id integer, updated_at timestamp, activity_type_code varchar(255), activity_type_title varchar(255), created_by varchar(255), deleted_by varchar(255), updated_by varchar(255), primary key (id), foreign key (activity_id) references taxpayer_activity_type (id));

CREATE INDEX idx_debt_inquiry_execution_paper on debt_inquiry_result (execution_paper_id);
CREATE INDEX idx_debt_paper_push_execution on debt_paper_push_record (execution_paper_id);
CREATE INDEX idx_fake_sanim_debt_execution_paper on fake_sanim_debt_inquiry_request (execution_paper_id);
CREATE INDEX idx_sanim_audit_occurred on sanim_audit_entry (occurred_at);
CREATE INDEX idx_sanim_audit_taxpayer on sanim_audit_entry (taxpayer_type, taxpayer_identifier);
